    44→/// Power target specification.
    45→#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
    46→#[serde(rename_all = "snake_case")]
    47→pub enum PowerTarget {
    48→    /// Fixed wattage target
    49→    Absolute { watts: u16 },
    50→    /// Percentage of user's FTP
    51→    PercentFtp { percent: u8 },
    52→    /// Range for ramps (start to end)
    53→    Range {
    54→        start: Box<PowerTarget>,
    55→        end: Box<PowerTarget>,
    56→    },
    57→}
    58→
    59→impl PowerTarget {
    60→    /// Create an absolute power target.
    61→    pub fn absolute(watts: u16) -> Self {
    62→        PowerTarget::Absolute { watts }
    63→    }
    64→
    65→    /// Create a percent FTP target.
    66→    pub fn percent_ftp(percent: u8) -> Self {
    67→        PowerTarget::PercentFtp { percent }
    68→    }
    69→
    70→    /// Create a range target for ramps.
    71→    pub fn range(start: PowerTarget, end: PowerTarget) -> Self {
    72→        PowerTarget::Range {
    73→            start: Box::new(start),
    74→            end: Box::new(end),
    75→        }
    76→    }
    77→
    78→    /// Calculate the actual wattage for a given FTP.
    79→    pub fn to_watts(&self, ftp: u16) -> u16 {
    80→        match self {
    81→            PowerTarget::Absolute { watts } => *watts,
    82→            PowerTarget::PercentFtp { percent } => (ftp as f32 * *percent as f32 / 100.0) as u16,
    83→            PowerTarget::Range { start, .. } => start.to_watts(ftp),
    84→        }
    85→    }
    86→
    87→    /// Calculate the actual wattage at a point in a range (0.0 to 1.0 progress).
    88→    pub fn to_watts_at(&self, ftp: u16, progress: f32) -> u16 {
    89→        match self {
    90→            PowerTarget::Absolute { watts } => *watts,
    91→            PowerTarget::PercentFtp { percent } => (ftp as f32 * *percent as f32 / 100.0) as u16,
    92→            PowerTarget::Range { start, end } => {
    93→                let start_watts = start.to_watts(ftp) as f32;
    94→                let end_watts = end.to_watts(ftp) as f32;
    95→                let progress = progress.clamp(0.0, 1.0);
    96→                (start_watts + (end_watts - start_watts) * progress) as u16
    97→            }
    98→        }
    99→    }
   100→}
