     1→//! CSV export functionality for ride data.
     2→//!
     3→//! T098: Implement CSV export of raw samples
     4→
     5→use crate::recording::types::{ExportError, Ride, RideSample};
     6→use chrono::Duration;
     7→use std::io::Write;
     8→
     9→/// Export ride samples to CSV format.
    10→pub fn export_csv(ride: &Ride, samples: &[RideSample]) -> Result<String, ExportError> {
    11→    if samples.is_empty() {
    12→        return Err(ExportError::NoData);
    13→    }
    14→
    15→    let mut output = Vec::new();
    16→
    17→    // Write header
    18→    writeln!(
    19→        output,
    20→        "timestamp,elapsed_seconds,power_watts,cadence_rpm,heart_rate_bpm,speed_kmh,distance_meters,calories,target_power"
    21→    )
    22→    .map_err(|e| ExportError::WriteFailed(e.to_string()))?;
    23→
    24→    // Write data rows
    25→    for sample in samples {
    26→        let timestamp = ride.started_at + Duration::seconds(sample.elapsed_seconds as i64);
    27→        writeln!(
    28→            output,
    29→            "{},{},{},{},{},{},{:.1},{},{}",
    30→            timestamp.to_rfc3339(),
    31→            sample.elapsed_seconds,
    32→            sample.power_watts.map_or(String::new(), |v| v.to_string()),
    33→            sample.cadence_rpm.map_or(String::new(), |v| v.to_string()),
    34→            sample
